use std :: path :: { Path , PathBuf } ; use std :: time :: SystemTime ; use anyhow :: { Context , Result } ; use crate :: cli :: LogsArgs ; # [doc = " Returns the path of the most recently modified file inside `log_dir`."] # [doc = ""] # [doc = " Uses a linear O(n) scan rather than sorting — we only need the maximum."] async fn latest (log_dir : & Path) -> Result < PathBuf > { let files = collect_files (log_dir) . await ? ; files . into_iter () . max_by_key (| (mtime , _) | * mtime) . map (| (_ , p) | p) . ok_or_else (| | anyhow :: anyhow ! ("No log files found in {}" , log_dir . display ())) }